package net.civeira.phylax.features.document.templateasset.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.templateasset.domain.TemplateAsset;
import net.civeira.phylax.features.document.templateasset.domain.gateway.TemplateAssetCursor;
import net.civeira.phylax.features.document.templateasset.domain.gateway.TemplateAssetFilter;

class TemplateAssetSlider extends Slider<TemplateAsset> {

  /**
   * @autogenerated SlideGenerator
   */
  private final TemplateAssetCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final TemplateAssetFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<TemplateAssetFilter, TemplateAssetCursor, Iterator<TemplateAsset>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  TemplateAssetSlider(final Iterator<TemplateAsset> multi, final int limit,
      final BiFunction<TemplateAssetFilter, TemplateAssetCursor, Iterator<TemplateAsset>> gateway,
      final TemplateAssetFilter filter, final TemplateAssetCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param templateAssets
   * @param limit
   * @return
   */
  @Override
  public Iterator<TemplateAsset> next(List<TemplateAsset> templateAssets, int limit) {
    TemplateAsset last = templateAssets.get(templateAssets.size() - 1);
    TemplateAssetCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
